/*
 * A257885  Sequence (a(n)) generated by Algorithm (in Comments) with a(1) = 0
 *          and d(1) = 2.
 * https://oeis.org/A257885
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 194, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A257885: 
 * a(1)=0, d(1)=2.  For k>=1 let
 *  h = the least integer > -a(k) such that h∉{d(1)…d(k)} and a(k)+h∉{a(1)…a(k)}.
 * Then a(k+1)=a(k)+h, d(k+1)=h.
 */

#include <stdlib.h>
#include <stdbool.h>

/* static storage for the sequence and the differences */
static seq_t *A = NULL;        /* array of a(k) */
static seq_t *D = NULL;        /* array of d(k) */
static size_t sizeA = 0;       /* number of elements stored (>=1 after init) */
static size_t sizeD = 0;
static size_t capA  = 0;       /* allocated capacity */
static size_t capD  = 0;

/* grow capacity of an array to at least 'needed' */
static void ensure_A(size_t needed)
{
    if (needed <= capA) return;
    size_t newcap = capA ? capA * 2 : 16;
    while (newcap < needed) newcap <<= 1;
    seq_t *tmp = (seq_t *)realloc(A, newcap * sizeof(seq_t));
    A = tmp;
    capA = newcap;
}

static void ensure_D(size_t needed)
{
    if (needed <= capD) return;
    size_t newcap = capD ? capD * 2 : 16;
    while (newcap < needed) newcap <<= 1;
    seq_t *tmp = (seq_t *)realloc(D, newcap * sizeof(seq_t));
    D = tmp;
    capD = newcap;
}

/* linear search: does 'arr[0 … len-1]' contain 'val'? */
static bool contains(const seq_t *arr, size_t len, seq_t val)
{
    for (size_t i = 0; i < len; ++i)
        if (arr[i] == val) return true;
    return false;
}

/* compute a(n) */
seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;      /* undefined, but safe */

    /* initialise on first call */
    if (sizeA == 0)
    {
        ensure_A(1);
        ensure_D(1);
        A[0] = (seq_t)0;
        D[0] = (seq_t)2;
        sizeA = sizeD = 1;
    }

    /* extend the sequence up to n */
    while (sizeA < n)
    {
        seq_t ak = A[sizeA - 1];    /* a(k) */
        /* determine smallest h > -ak that is not used and keeps a+ h unique */
        seq_t h = -(ak) + (seq_t)1; /* starts at -ak+1, works for all ak>=0 */

        /* find minimal eligible h */
        while (true)
        {
            if (!contains(D, sizeD, h) && !contains(A, sizeA, ak + h))
                break;
            ++h;
        }

        /* store new elements */
        ensure_A(sizeA + 1);
        ensure_D(sizeD + 1);
        A[sizeA] = ak + h;
        D[sizeD] = h;
        ++sizeA;
        ++sizeD;
    }

    return A[n - 1];
}
